function resolveSafeDir(dir, debug, label) {
  let realDir;
  try {
    const lstat = fs.lstatSync(dir);
    if (lstat.isSymbolicLink()) {
      realDir = fs.realpathSync(dir);
      const realStat = fs.statSync(realDir);
      if (!realStat.isDirectory()) {
        if (debug) process.stderr.write(`[caveman] ${label}: symlink target ${realDir} is not a directory\n`);
        return null;
      }
      if (typeof process.getuid === 'function') {
        if (realStat.uid !== process.getuid()) {
          if (debug) process.stderr.write(`[caveman] ${label}: symlink target ${realDir} owned by uid ${realStat.uid}\n`);
          return null;
        }
      } else {
        const home = os.homedir();
        const normalized = path.resolve(realDir).toLowerCase();
        const normalizedHome = path.resolve(home).toLowerCase();
        if (!normalized.startsWith(normalizedHome + path.sep) && normalized !== normalizedHome) {
          if (debug) process.stderr.write(`[caveman] ${label}: symlink target ${normalized} is outside home\n`);
          return null;
        }
      }
    } else {
      realDir = dir;
    }
  } catch (e) {
    return null;
  }
  return realDir;
}

